-- Generated by `chainindex dbt` from chains/ethereum.yaml and abis/ERC20.json. Do not edit: change the chain file or ABI and regenerate.
-- Approval(address,address,uint256)
{{ config(
    materialized='view',
    schema='events_ethereum',
    alias='usdc__approval',
    tags=['chains', 'chain_ethereum'],
) }}

select
    toUInt64(1) as chain_id,
    address,
    block_number,
    block_time,
    block_hash,
    transaction_hash,
    transaction_index,
    log_index,
    inserted_at,
    concat('0x', substring(substring(topic1, 3, 64), 25, 40)) as owner,
    concat('0x', substring(substring(topic2, 3, 64), 25, 40)) as spender,
    reinterpretAsUInt256(reverse(unhex(substring(data, 3, 64)))) as value
from {{ source('chain_ethereum', 'logs') }}
where topic0 = '0x8c5be1e5ebec7d5bd14f71427d1e84f3dd0314c0f7b2291e5b200ac8c7c3b925'
  and address in (select address from {{ ref('ethereum__contracts') }} where contract = 'usdc')
  and (block_number, block_hash) not in (
    select block_number, block_hash from {{ source('chain_ethereum', 'orphaned_blocks') }}
  )
